diff --git a/INSTALL.md b/INSTALL.md
index f41a035bd..c8328856d 100644
--- a/INSTALL.md
+++ b/INSTALL.md
@@ -7,6 +7,7 @@ This guide covers installing and setting up kspec in your own projects. For deve
 - **Node.js** v18 or later
 - **npm** (or pnpm/yarn)
 - **Git** - Your project must be a git repository for shadow branch mode (the default)
+- **Bun** (optional) - Required only for the daemon/web UI (`kspec serve`). Not needed for CLI-only usage. Install from [bun.sh](https://bun.sh/docs/installation)

 ## Installation

@@ -141,6 +142,7 @@ See [docs/getting-started.md](docs/getting-started.md) for the full first-task w

 | Issue | Solution |
 |-------|----------|
+| "Bun runtime is required" | Install Bun: `curl -fsSL https://bun.sh/install \| bash` (only needed for `kspec serve`) |
 | "kspec: command not found" | Run `npm install -g @kynetic-ai/spec`, or if using source: `npm link` |
 | "Not a git repository" | Run `git init` first, or use `kspec init --no-shadow` |
 | "Cannot find .kspec" | Run `kspec init` (fresh project) or `kspec setup --auto-worktree` (cloned repo) |
diff --git a/docs/getting-started.md b/docs/getting-started.md
index 7d5d48684..67519c2fe 100644
--- a/docs/getting-started.md
+++ b/docs/getting-started.md
@@ -17,6 +17,7 @@ The example uses a documentation deliverable so you can try the whole flow in al
 - Node.js 18+
 - Git repository initialized locally
 - `gh` installed if you want to open a pull request from the command line
+- [Bun](https://bun.sh) installed if you plan to use the web dashboard (`kspec serve`)

 If you need install variants, cloned-project setup, or troubleshooting, read [INSTALL.md](../INSTALL.md) first.

diff --git a/src/cli/commands/serve.ts b/src/cli/commands/serve.ts
index a8571584c..d13be2a11 100644
--- a/src/cli/commands/serve.ts
+++ b/src/cli/commands/serve.ts
@@ -269,13 +269,22 @@ async function startServer(opts: {
     process.exit(EXIT_CODES.ERROR);
   }

-  // Daemon requires Bun to run TypeScript directly
+  // AC: @web-ui ac-2 — clear error with install URL when Bun is missing
   if (!isBunAvailable()) {
+    const installHint = process.platform === 'win32'
+      ? 'Install Bun: powershell -c "irm bun.sh/install.ps1 | iex"'
+      : 'Install Bun: curl -fsSL https://bun.sh/install | bash';
     if (isJsonMode()) {
-      output({ error: 'Bun runtime not found', hint: 'Install Bun: https://bun.sh/docs/installation' });
+      output({
+        error: 'Bun runtime is required for the kspec daemon',
+        hint: installHint,
+        url: 'https://bun.sh/docs/installation',
+      });
     } else {
-      error('Bun runtime is required for the daemon server');
-      error('Install Bun: https://bun.sh/docs/installation');
+      error('Bun runtime is required for the kspec daemon');
+      error('The daemon uses Elysia (a Bun-native framework) and cannot run on Node.js alone.');
+      info(installHint);
+      info('For more options: https://bun.sh/docs/installation');
     }
     process.exit(EXIT_CODES.ERROR);
   }
diff --git a/tests/cli-serve.test.ts b/tests/cli-serve.test.ts
index 20f7e0282..7ffc1dff1 100644
--- a/tests/cli-serve.test.ts
+++ b/tests/cli-serve.test.ts
@@ -14,7 +14,7 @@ import {
   type KspecOptions,
 } from './helpers/cli';
 import { spawn, execSync } from 'child_process';
-import { join } from 'path';
+import { dirname, join } from 'path';
 import { readFileSync, existsSync, mkdirSync } from 'fs';
 import { createServer } from 'net';

@@ -569,6 +569,99 @@ describe('kspec serve commands', () => {
     expect(result.stderr).toContain('Try: kspec serve --port');
   });

+  // AC: @web-ui ac-1
+  it('should bundle daemon runtime dependencies in the npm package', async () => {
+    // Pack the project, install the tarball into an isolated directory,
+    // and verify that the daemon binary and its runtime imports resolve.
+    const projectRoot = join(__dirname, '..');
+    const installDir = await createTempDir();
+
+    try {
+      // Fresh pack so we test the current build output
+      const packOutput = execSync('npm pack --pack-destination ' + installDir, {
+        cwd: projectRoot,
+        encoding: 'utf-8',
+        stdio: ['pipe', 'pipe', 'pipe'],
+      }).trim();
+      const tarball = join(installDir, packOutput.split('\n').pop()!.trim());
+
+      // Install the tarball into the temp dir (brings transitive deps)
+      execSync(`npm init -y && npm install --no-save "${tarball}"`, {
+        cwd: installDir,
+        encoding: 'utf-8',
+        stdio: ['pipe', 'pipe', 'pipe'],
+        timeout: 60_000,
+      });
+
+      // Resolve the installed package's dist/daemon/index.ts
+      const installedPkgDir = join(installDir, 'node_modules', '@kynetic-ai', 'spec');
+      const daemonEntry = join(installedPkgDir, 'dist', 'daemon', 'index.ts');
+      expect(existsSync(daemonEntry), `daemon entry not found at ${daemonEntry}`).toBe(true);
+
+      // Verify runtime dependencies resolve from the installed location
+      const depsToCheck = ['elysia', '@elysiajs/cors', '@elysiajs/static'];
+      for (const dep of depsToCheck) {
+        const resolved = require.resolve(dep, { paths: [installedPkgDir] });
+        expect(resolved, `${dep} should resolve from installed package`).toBeTruthy();
+      }
+    } finally {
+      await cleanupTempDir(installDir);
+    }
+  }, 90_000);
+
+  // AC: @web-ui ac-2
+  it('should show clear error with Bun install URL when Bun is not available', () => {
+    // Build PATH that includes node but excludes bun
+    const nodeDir = dirname(execSync('which node', { encoding: 'utf-8' }).trim());
+    const noBunPath = (process.env.PATH || '')
+      .split(':')
+      .filter(p => {
+        try { return !existsSync(join(p, 'bun')); } catch { return true; }
+      })
+      .join(':');
+    // Ensure node's directory is always present
+    const pathWithNode = noBunPath.includes(nodeDir) ? noBunPath : `${nodeDir}:${noBunPath}`;
+
+    const result = runKspec(
+      `serve start --kspec-dir ${join(tempDir, '.kspec')}`,
+      tempDir,
+      { expectFail: true, env: { PATH: pathWithNode } }
+    );
+
+    expect(result.exitCode).not.toBe(0);
+    expect(result.stderr).toContain('Bun runtime is required');
+    // Install instructions go to stdout via info()
+    expect(result.stdout).toContain('bun.sh');
+  });
+
+  // AC: @web-ui ac-2
+  it('should show Bun install URL in JSON mode when Bun is not available', () => {
+    // Build PATH that includes node but excludes bun
+    const nodeDir = dirname(execSync('which node', { encoding: 'utf-8' }).trim());
+    const noBunPath = (process.env.PATH || '')
+      .split(':')
+      .filter(p => {
+        try { return !existsSync(join(p, 'bun')); } catch { return true; }
+      })
+      .join(':');
+    const pathWithNode = noBunPath.includes(nodeDir) ? noBunPath : `${nodeDir}:${noBunPath}`;
+
+    const result = runKspec(
+      `serve start --json --kspec-dir ${join(tempDir, '.kspec')}`,
+      tempDir,
+      { expectFail: true, env: { PATH: pathWithNode } }
+    );
+
+    expect(result.exitCode).not.toBe(0);
+    const parsed = JSON.parse(result.stdout);
+    expect(parsed).toHaveProperty('error');
+    expect(parsed.error).toContain('Bun runtime is required');
+    expect(parsed).toHaveProperty('hint');
+    expect(parsed.hint).toContain('bun.sh');
+    expect(parsed).toHaveProperty('url');
+    expect(parsed.url).toBe('https://bun.sh/docs/installation');
+  });
+
   // AC: @cli-serve-commands ac-11
   describe('dispatch agent guard', () => {
     // AC: @trait-semantic-exit-codes ac-2 — validation error exit code
```

